using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckDodgeball {
public sealed class DodgeFighter:MonoBehaviour {
 public DodgeMatch match;public SportsEventTruck truck;public int slot;public Transform strikeHalo;public Renderer[] teamTrim;MaterialPropertyBlock teamBlock;Renderer[] ghostTrim;public ParticleSystem hit;public Vector3 Incoming{get;private set;}public Vector3 Facing{get;private set;}=Vector3.forward;public float StrikeStart{get;private set;}=-100;public float StrikeUntil{get;private set;}=-100;public float Cooldown{get;private set;}public int Bounces{get;private set;}public bool Airborne{get;private set;}
 readonly SportsLimitedAftertouch touch=new SportsLimitedAftertouch();float bounceCooldown,roofAge,lastContact=-100;DodgeTrampoline contactTile;
 void PaintTeam(){if(teamBlock==null)teamBlock=new MaterialPropertyBlock();var color=match.rules.Team(slot)==0?new Color(.1f,.6f,1):new Color(1,.3f,.05f);teamBlock.SetColor("_BaseColor",color);teamBlock.SetColor("_Color",color);foreach(var trim in teamTrim)trim.SetPropertyBlock(teamBlock);if(ghostTrim==null){var all=match.replay.ghosts[slot].GetComponentsInChildren<Renderer>(true);var list=new System.Collections.Generic.List<Renderer>();foreach(var renderer in all)if(renderer.name.StartsWith("Team stripe"))list.Add(renderer);ghostTrim=list.ToArray();}foreach(var trim in ghostTrim)trim.SetPropertyBlock(teamBlock);}
 public void ResetFighter(Vector3 p,Quaternion q){PaintTeam();truck.Prepare(p,q);truck.Power(false);truck.body.isKinematic=true;Cooldown=bounceCooldown=roofAge=0;StrikeStart=StrikeUntil=lastContact=-100;Bounces=0;Airborne=false;Facing=q*Vector3.forward;touch.Reset(1.8f,Vector2.zero);strikeHalo.gameObject.SetActive(false);hit.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);}
 public bool ActiveStrike(float time)=>time>=StrikeStart&&time<=StrikeUntil;
 public bool CanReturn(DodgeBall ball,float time){var delta=ball.body.worldCenterOfMass-truck.body.worldCenterOfMass;var flat=Vector3.ProjectOnPlane(delta,Vector3.up);return ActiveStrike(time)&&delta.sqrMagnitude<3.8f*3.8f&&Mathf.Abs(delta.y)<2.9f&&(flat.sqrMagnitude<.1f||Vector3.Dot(Facing,flat.normalized)>-.05f);}
 public void Returned(){StrikeUntil=-100;strikeHalo.gameObject.SetActive(false);}
 public void Step(Vector2 input,bool strike,float dt){if(!match.rules.alive[slot])return;Cooldown=Mathf.Max(0,Cooldown-dt);bounceCooldown=Mathf.Max(0,bounceCooldown-dt);var flat=Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up);if(flat.sqrMagnitude>.1f)Facing=flat.normalized;truck.TickDrive(input);DodgeTrampoline tile=null;foreach(var wheel in truck.wheels)if(wheel.IsGrounded&&wheel.HitCollider!=null&&wheel.HitNormal.y>.65f&&(wheel.HitPoint-wheel.transform.position).sqrMagnitude<2){tile=wheel.HitCollider.GetComponent<DodgeTrampoline>();if(tile!=null)break;}if(tile==null&&Time.fixedTime-lastContact<.06f)tile=contactTile;
 if(tile!=null&&bounceCooldown<=0&&truck.body.linearVelocity.y<.6f){float add=Mathf.Max(0,7.8f-truck.body.linearVelocity.y);truck.body.AddForce(Vector3.up*add,ForceMode.VelocityChange);bounceCooldown=.5f;Bounces++;match.BounceCount++;tile.Bounce();touch.Reset(1.8f,Vector2.zero);match.feedback.Play(0,0,true);match.Pulse(slot,.1f,.05f);}Airborne=!truck.Grounded||truck.body.linearVelocity.y>.6f;if(Airborne){var world=Facing*input.y+Vector3.Cross(Vector3.up,Facing)*input.x;touch.Tick(truck.body,new Vector2(world.x,world.z),dt,1.2f);if(touch.Spent<1.8f)truck.body.AddTorque(Vector3.up*input.x*1.8f,ForceMode.Acceleration);}float up=Vector3.Dot(truck.transform.up,Vector3.up);roofAge=up<.75f&&!truck.Grounded?roofAge+dt:0;if(roofAge>1&&input.sqrMagnitude>.1f){var axis=Vector3.Cross(truck.transform.up,Vector3.up);if(axis.sqrMagnitude<.03f)axis=truck.transform.forward;truck.body.AddTorque(axis.normalized*1.5f-truck.body.angularVelocity*.5f,ForceMode.Acceleration);}
 if(strike&&Cooldown<=0){Cooldown=1.05f;StrikeStart=Time.fixedTime;StrikeUntil=StrikeStart+.24f;}strikeHalo.gameObject.SetActive(ActiveStrike(Time.fixedTime));Incoming=truck.body.linearVelocity;}
 public void Eliminate(){truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;strikeHalo.gameObject.SetActive(false);hit.transform.position=truck.body.worldCenterOfMass;hit.Play();match.feedback.Play(3,0,true);match.Pulse(slot,.4f,.15f);gameObject.SetActive(false);}
 void OnCollisionStay(Collision collision){if(!match.Live||match.Stage!=DodgeStage.Playing)return;var tile=collision.collider.GetComponent<DodgeTrampoline>();if(tile==null)return;for(int i=0;i<collision.contactCount;i++)if(collision.GetContact(i).normal.y>.65f){contactTile=tile;lastContact=Time.fixedTime;break;}}
 public void Freeze(){truck.Power(false);truck.body.isKinematic=true;strikeHalo.gameObject.SetActive(false);}
}
}
